price_badge.expr:
(
  $ranges := {
    "gpt-image-1": {
      "low":    [0.011, 0.02],
      "medium": [0.042, 0.07],
      "high":   [0.167, 0.25]
    },
    "gpt-image-1.5": {
      "low":    [0.009, 0.02],
      "medium": [0.034, 0.062],
      "high":   [0.133, 0.22]
    },
    "gpt-image-2": {
      "low":    [0.0058, 0.0228],
      "medium": [0.0492, 0.2016],
      "high":   [0.198, 0.804]
    }
  };
  $range := $lookup($lookup($ranges, widgets.model), widgets.quality);
  $nRaw := widgets.n;
  $n := ($nRaw != null and $nRaw != 0) ? $nRaw : 1;
  ($n = 1)
    ? {"type":"range_usd","min_usd": $range[0], "max_usd": $range[1], "format": {"approximate": true}}
    : {
        "type":"range_usd",
        "min_usd": $range[0] * $n,
        "max_usd": $range[1] * $n,
        "format": { "suffix": "/Run", "approximate": true }
      }
)
